solution.solution.rs:
fn report(names: &[String]) -> String {
    if names.is_empty() {
        return "no names".to_string();
    }
    format!("{} names: {}", names.len(), names.join(", "))
}

fn longest(a: &str, b: &str) -> String {
    if b.len() > a.len() { b.to_string() } else { a.to_string() }
}

fn shout(mut text: String) -> String {
    text.make_ascii_uppercase();
    text.push('!');
    text
}

fn add_suffix(names: &mut Vec<String>, suffix: &str) {
    for name in names.iter_mut() {
        name.push_str(suffix);
    }
}

unitTests:
test("report borrows", || {
    let names = vec!["Ada".to_string(), "Grace".to_string(), "Linus".to_string()];
    check_eq(report(&names), "3 names: Ada, Grace, Linus");
    check_eq(names.len(), 3);
    check_eq(report(&names[..1]), "1 names: Ada");
    check_eq(report(&[]), "no names");
});

test("longest borrows both", || {
    let a = String::from("tea");
    let b = String::from("coffee");
    check_eq(longest(&a, &b), "coffee");
    check_eq(longest(&a, "cup"), "tea");
    check_eq(a + &b, "teacoffee");
});

test("shout takes ownership", || {
    let s = String::from("hello");
    let loud = shout(s);
    check_eq(loud, "HELLO!");
    check_eq(shout(String::new()), "!");
});

test("add_suffix borrows mutably", || {
    let mut team = vec!["ada".to_string(), "bob".to_string()];
    add_suffix(&mut team, "@example.org");
    add_suffix(&mut team, "!");
    check_eq(team, vec!["ada@example.org!", "bob@example.org!"]);
});

